<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import { NButton,NInput,NSelect } from 'naive-ui'
import { api } from '../../shared/api'
import { useResource,formatDate,formatBytes,percent } from '../../shared/ui/resource'
import { useRealtime } from '../../shared/realtime/useRealtime'
import Icon from '../../shared/ui/Icon.vue'
import EmptyState from '../../shared/ui/EmptyState.vue'
import StatusBadge from '../../shared/ui/StatusBadge.vue'
import ErrorBanner from '../../shared/ui/ErrorBanner.vue'
import ResourceChart from './ResourceChart.vue'
const {data,error,loading,refresh}=useResource(api.runtime)
const logSearch=ref(''),logLevel=ref('')
const {data:logs,error:logError,refresh:refreshLogs}=useResource(()=>api.logs(logSearch.value,logLevel.value))
const {connected}=useRealtime(()=>void refresh())
const warnings=computed(()=>data.value?.services.filter(s=>s.status!=='ready')??[])
const readyModels=computed(()=>data.value?.models.filter(model=>model.status==='ready').length??0)
const polling=setInterval(()=>void refresh(),10000);onUnmounted(()=>clearInterval(polling))
</script>
<template><div class="page-heading"><div><h1>运行状态</h1><p>查看设备、服务、模型与计算资源的实时状态</p></div><div class="heading-actions"><span class="clock">{{data?`采样于 ${formatDate(data.observed_at)}`:'等待采样'}}</span><NButton size="small" :loading="loading" @click="refresh"><template #icon><Icon name="refresh" :size="15"/></template>刷新</NButton></div></div><ErrorBanner :error="error" @retry="refresh"/><div class="stats-grid"><div class="panel stat"><div class="stat-icon"><Icon name="monitor" :size="27"/></div><div><div class="stat-label">视频源在线数</div><div class="stat-value">{{data?.sources.online??'—'}} <small>/ {{data?.sources.total??'—'}}</small></div><div class="stat-note">独立连接状态</div></div></div><div class="panel stat"><div class="stat-icon green"><Icon name="cpu" :size="27"/></div><div><div class="stat-label">计算资源使用率</div><div style="font-size:12px;margin-top:8px">CPU <b>{{percent(data?.cpu_percent)}}</b></div><div class="stat-note">内存 {{percent(data?.memory_percent)}} · GPU {{percent(data?.gpu_percent)}}</div></div></div><div class="panel stat"><div class="stat-icon purple"><Icon name="database" :size="27"/></div><div><div class="stat-label">可用存储空间</div><div class="stat-value" style="font-size:22px">{{data?formatBytes(data.disk.free_bytes):'—'}}</div><div class="stat-note">{{data?`总容量 ${formatBytes(data.disk.total_bytes)}`:'等待资源采样'}}</div></div></div><div class="panel stat"><div class="stat-icon orange"><Icon name="box" :size="27"/></div><div><div class="stat-label">已登记模型版本</div><div class="stat-value">{{data?.models.length??'—'}} <small>个</small></div><div class="stat-note">{{data?`${readyModels} 个当前可执行`:'等待读取模型状态'}}</div></div></div></div><div class="runtime-main"><section class="panel"><div class="panel-title"><h2>计算资源趋势</h2><small>服务启动以来的实测采样</small></div><div class="chart-legend"><span><i class="dot" style="color:#3584ee"/>CPU 使用率</span><span><i class="dot" style="color:#39af83"/>内存使用率</span><span><i class="dot" style="color:#8664d9"/>GPU {{data?.gpu_percent==null?'未知':'使用率'}}</span></div><ResourceChart v-if="data?.history.length" :samples="data.history"/><EmptyState v-else title="等待资源采样" description="图表只展示服务采集的真实历史数据。" icon="activity"/><div class="muted" style="font-size:10px">{{connected?'实时状态通知已连接':'实时通知重连中，页面每 10 秒刷新'}}</div></section><section class="panel"><div class="panel-title"><h2>服务运行状态</h2><small>{{data?.services.length??0}} 项服务</small></div><template v-if="data?.services.length"><div v-for="service in data.services" :key="service.key" class="service-row"><div class="stat-icon" :class="service.status==='ready'?'green':''"><Icon :name="service.key.includes('worker')?'cpu':service.key.includes('media')?'video':'server'"/></div><div><h3>{{service.name}}</h3><small>{{service.message}}</small></div><StatusBadge :value="service.status"/></div></template><EmptyState v-else title="等待服务状态" compact/></section></div><div class="runtime-bottom"><section class="panel"><div class="panel-title"><h2>模型可用性</h2><small>{{readyModels}} / {{data?.models.length??0}} 可执行</small></div><template v-if="data?.models.length"><div v-for="model in data.models" :key="`${model.id}:${model.version}`" class="service-row" data-testid="runtime-model"><div class="stat-icon" :class="model.status==='ready'?'green':''"><Icon name="box"/></div><div><h3>{{model.name}} · {{model.version}}</h3><small>{{model.template_name}} · {{model.runtime_type}}</small><small>{{model.message}}</small></div><StatusBadge :value="model.status"/></div></template><EmptyState v-else title="尚未登记本地模型" description="请先在模型管理中导入并校验受支持的本地模型版本。" icon="box" compact/></section><section class="panel"><div class="panel-title"><h2>异常提醒与建议</h2><small>{{warnings.length}} 项需关注</small></div><div v-for="service in warnings" :key="service.key" class="service-row"><Icon name="alert" style="color:#e49b39;flex-shrink:0"/><div><h3>{{service.name}}未就绪</h3><small>{{service.message}}</small></div></div><EmptyState v-if="!warnings.length" title="暂无服务异常" description="以最近一次实际采样结果为准。" compact icon="check"/></section></div><section class="panel" style="margin-top:18px"><div class="panel-title"><h2>最近告警 / 系统日志</h2><form class="toolbar" style="margin:0" @submit.prevent="refreshLogs"><NSelect v-model:value="logLevel" :options="[{label:'全部级别',value:''},{label:'错误',value:'ERROR'},{label:'警告',value:'WARNING'},{label:'信息',value:'INFO'}]" aria-label="日志级别" @update:value="refreshLogs"/><NInput v-model:value="logSearch" placeholder="搜索日志内容…" aria-label="搜索日志" style="width:180px"/><NButton size="small" attr-type="submit">查询</NButton></form></div><ErrorBanner :error="logError" @retry="refreshLogs"/><div v-if="logs?.items.length" class="table-wrap"><table><thead><tr><th>时间</th><th>级别</th><th>模块</th><th>消息内容</th></tr></thead><tbody><tr v-for="log in logs.items" :key="log.id"><td>{{formatDate(log.occurred_at)}}</td><td><span class="status" :class="log.level==='ERROR'?'bad':log.level==='WARNING'?'warn':''">{{log.level}}</span></td><td>{{log.module}}</td><td class="wrap">{{log.message}}</td></tr></tbody></table></div><EmptyState v-else title="暂无日志记录" compact icon="file-plus"/></section></template>
